const tools = [{
  name: 'get_weather',
  description: '도시의 현재 날씨를 조회한다',
  input_schema: {
    type: 'object',
    properties: { city: { type: 'string', description: '도시 이름' } },
    required: ['city'],
  },
}];
// 모델은 도구를 「부를지」 정하고, 스키마에 맞는 인자를 만든다
// 실제 실행은 우리 코드가 한다 (프롬프트 칸 7장의 구조화 출력)

let messages = [{ role: 'user', content: question }];
for (let turn = 0; turn < MAX_TURNS; turn++) {          // 상한 필수!
  const res = await client.create({ model, tools, messages });
  if (res.stop_reason !== 'tool_use') return res;       // 도구 안 부르면 끝
  messages.push(res.message);
  for (const call of res.toolCalls) {
    const result = await runTool(call.name, call.input); // 우리가 실행
    messages.push({ role: 'tool', tool_call_id: call.id, content: result });
  }
}
throw new Error('최대 반복 초과');                        // 폴백 (5장)

async function runTool(name, input) {
  try {
    const order = await db.findOrder(input.order_id, currentUser.id);
    if (!order) return { error: 'not_found', message: `주문 ${input.order_id} 없음` };
    return { status: order.status, eta: order.eta };
  } catch (e) {
    return { error: 'internal', message: '조회 실패, 잠시 후 재시도' };
    // 예외를 던지면 루프가 깨진다 — 결과로 주면 모델이 대처한다
  }
}

const limits = {
  maxTurns: 10,             // 반복 상한
  maxTokens: 50000,        // 예산
  maxSameCall: 2,          // 같은 호출 반복 감지
  timeout: 60000,          // 전체 시간
};
// 각 턴마다 검사 -> 초과하면 중단하고 폴백
// 파괴적 도구는 사람 승인 게이트 (6장)
// 최종 결과는 검증 후 반환 (환각 칸 6장)
